"use client"

import React, { useEffect, useState } from "react";
import axios from "axios";
import { formatCurrency } from "@/lib/utils/formatCurrency";
import { useRouter } from "next/navigation";
import { getAccessToken } from "@/lib/utils/auth";

interface DetailPaymentProps {
  subtotal: number;
  shippingFee: number;
  totalPrice: number;
}

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;
const accessToken = getAccessToken();

const DetailPayment: React.FC<DetailPaymentProps> = ({ subtotal, shippingFee, totalPrice }) => {
  const router = useRouter();
  const [paymentMethods, setPaymentMethods] = useState<{ id: number; name: string }[]>([]);
  const [selectedMethod, setSelectedMethod] = useState<number | null>(null);

  useEffect(() => {
    const fetchPaymentMethods = async () => {
      try {
        const response = await axios.get(`${API_BASE_URL}/payments/methods`, {
          headers: {
            Authorization: `Bearer ${accessToken}`,
          },
        });
        setPaymentMethods(response.data.data);
      } catch (error) {
        console.error("Error fetching payment methods:", error);
      }
    };

    fetchPaymentMethods();
  }, []);

  return (
    <div className="mt-6 p-6 bg-white shadow-md rounded-lg w-full">
      <h2 className="text-xl font-semibold mb-4 text-black">Payment Details</h2>

      <div className="text-black space-y-2">
        <p>
          <span className="font-semibold">Subtotal:</span> {formatCurrency(subtotal)}
        </p>
        <p>
          <span className="font-semibold">Shipping Fee:</span> {formatCurrency(shippingFee)}
        </p>
        <p className="text-xl font-semibold border-t border-gray-300 pt-2">
          Total: {formatCurrency(totalPrice)}
        </p>
      </div>

      <div className="mt-4">
        <h3 className="text-lg font-semibold mb-2">Payment Method</h3>
        {paymentMethods.length > 0 ? (
          <div className="space-y-2">
            {paymentMethods.map((method) => (
              <label key={method.id} className="flex items-center space-x-2 cursor-pointer">
                <input
                  type="radio"
                  name="paymentMethod"
                  value={method.id}
                  checked={selectedMethod === method.id}
                  onChange={() => setSelectedMethod(method.id)}
                  className="form-radio text-green-600"
                />
                <span className="text-black">{method.name}</span>
              </label>
            ))}
          </div>
        ) : (
          <p className="text-gray-500">Loading payment methods...</p>
        )}
      </div>

      <button
        className="mt-6 px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-500 w-full"
        onClick={() => router.push("/checkout/payment")}
        disabled={!selectedMethod}
      >
        Proceed to Payment
      </button>
    </div>
  );
};

export default DetailPayment;
